window.CLASE={"temas": [{"name": "Espirometría y Radiografía de tórax", "tab": "Tema 1", "slides": [{"title": "Qué es y qué mide", "html": "<div class=\"bar\">Qué es y qué mide</div><ul><li>Prueba más simple y usada; <span class=\"ex\">con ella se diagnostica EPOC y asma</span></li><li><b>Capacidad vital forzada (CVF)</b>: aire que se expulsa a la fuerza desde la <b>capacidad pulmonar total (CPT)</b> hasta el <b>volumen residual (VR)</b></li><li><b>Volumen espiratorio forzado en 1 s (VEF1)</b>: lo que sale en el primer segundo</li><li><b>Cociente VEF1/CVF</b>: normal ≈ <span class=\"m\">80 %</span></li><li><b>Flujo espiratorio forzado 25–75 % (FEF25–75)</b>: tramo medio de la CVF</li></ul><div class=\"bar\">Valores de referencia</div><ul><li>Se comparan con sanos de misma <b>talla, edad, sexo y etnia</b></li><li>Límite inferior de lo normal = <span class=\"m\">percentil 5</span></li><li>Cociente normal: 0.70–0.80 a los 25 años y 0.63–0.68 a los 65</li></ul>", "book": [{"pn": "523", "k": 19, "img": "img/t1-s01-p019.jpg", "fuente": "Cecil"}, {"pn": "521", "k": 17, "img": "img/t1-s01-p017.jpg", "fuente": "Cecil"}], "q": [{"rep": 3, "q": "¿Qué valor establece el diagnóstico de obstrucción? (EPOC en fumador)", "a": "Relación VEF1/CVF", "e": "Obstrucción = relación VEF1/CVF disminuida (<0.70 o <LIN). VEF1 mide gravedad."}, {"rep": 2, "q": "¿Qué parámetro indica la severidad de la obstrucción?", "a": "Volumen espiratorio forzado en el 1er segundo", "e": "El VEF1 (% del predicho) gradúa la gravedad; la relación solo diagnostica."}, {"rep": 2, "q": "El diagnóstico espirométrico de restricción se sospecha por alteraciones en:", "a": "Capacidad vital forzada", "e": "CVF baja con relación normal/alta sugiere restricción; la confirmación requiere CPT."}]}, {"title": "Volúmenes y capacidades", "html": "<div class=\"bar\">Volúmenes y capacidades</div><div class=\"fig\"><svg viewBox=\"0 0 220 156\" width=\"220\" height=\"156\"><rect x=\"6\" y=\"110\" width=\"150\" height=\"30\" fill=\"#e6edf5\"/>\n<g stroke=\"#a9b4c0\" stroke-width=\"1\" stroke-dasharray=\"3 3\"><path d=\"M6 14H156M6 60H156M6 80H156M6 110H156\"/></g><path d=\"M6 140H156\" stroke=\"#14212e\" stroke-width=\"1.4\"/><path d=\"M6 140V8\" stroke=\"#14212e\" stroke-width=\"1.4\"/>\n<path d=\"M6 70q12-20 24 0t24 0t24 0C84 40 84 14 92 14L98 14C106 14 108 104 120 110L138 110C146 108 150 84 152 72\" fill=\"none\" stroke=\"#1f5f99\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n<g stroke=\"#12466e\" stroke-width=\"1.3\" fill=\"none\"><path d=\"M159 14H163V60H159M159 60H163V80H159M159 80H163V110H159M159 110H163V140H159\"/><path d=\"M193 14H197V110H193\"/></g>\n<g font-family=\"Geist,sans-serif\" font-weight=\"600\" font-size=\"10.5\" fill=\"#12466e\"><text x=\"168\" y=\"40\">VIR</text><text x=\"168\" y=\"74\">VT</text><text x=\"168\" y=\"99\">VER</text><text x=\"168\" y=\"129\">VR</text><text x=\"201\" y=\"66\" font-size=\"11\">CV</text><text x=\"8\" y=\"11\" font-size=\"9\" fill=\"#5f6b78\">CPT</text></g>\n<text x=\"8\" y=\"152\" font-family=\"Geist,sans-serif\" font-weight=\"600\" font-size=\"9\" fill=\"#5f6b78\">tiempo →</text><text x=\"3\" y=\"22\" font-family=\"Geist,sans-serif\" font-weight=\"600\" font-size=\"9\" fill=\"#5f6b78\" transform=\"rotate(-90 3 22)\" display=\"none\">V</text></svg></div><div class=\"t\"><div class=\"r\"><b>Volumen corriente (VT)</b> · respiración en reposo</div><div class=\"r\"><b>Volumen de reserva inspiratorio (VIR)</b> y <b>espiratorio (VER)</b> · lo que aún cabe tras un VT</div><div class=\"r\"><b>VR</b> · queda tras espirar al máximo; <span class=\"m\">no sale en espirometría</span></div></div><div class=\"bar\">Capacidades = suma de volúmenes</div><div class=\"t\"><div class=\"r\"><b>Capacidad vital (CV)</b> = VT + VIR + VER · <span class=\"ex\">de CPT a VR</span></div><div class=\"r\"><b>Capacidad inspiratoria (CI)</b> = VT + VIR</div><div class=\"r\"><b>Capacidad residual funcional (CRF)</b> = VER + VR · reposo</div><div class=\"r\"><b>CPT</b> = VR + VER + VT + VIR</div></div><p><span class=\"soft\">El espirómetro mide VT, VIR y VER.</span></p>", "book": [{"pn": "521", "k": 17, "img": "img/t1-s02-p017.jpg", "fuente": "Cecil"}], "q": []}, {"title": "Cuándo y cómo medir", "html": "<div class=\"bar\">Cuándo se indica</div><ul><li><span class=\"m\">Con síntomas</span>: confirma obstrucción</li><li><b>No</b> sirve de cribado en fumadores asintomáticos: lo normal da falsa seguridad</li></ul><div class=\"bar\">Cómo medir VR, CRF y CPT</div><div class=\"t\"><div class=\"r\"><b>Pletismografía</b> · ley de Boyle; <span class=\"m\">la más exacta</span>; sobrestima si el jadeo es rápido</div><div class=\"r\"><b>Dilución de helio</b> · subestima si hay bullas</div><div class=\"r\"><b>Lavado de nitrógeno (N₂)</b> · respirar oxígeno (O₂) al 100 %; también subestima</div></div><div class=\"bar\">Calidad de la prueba</div><ul><li>Máximo <span class=\"ex\"><span class=\"m2\">8 maniobras</span></span> de CVF</li><li>Entre los 2 mejores esfuerzos de CVF y VEF1: diferencia <span class=\"m2\">< 150 mL</span></li><li>Se inspecciona la curva flujo-volumen</li><li>Mala técnica da valores <b>falsamente bajos</b> y finge enfermedad</li></ul>", "book": [{"pn": "521", "k": 17, "img": "img/t1-s03-p017.jpg", "fuente": "Cecil"}, {"pn": "523", "k": 19, "img": "img/t1-s03-p019.jpg", "fuente": "Cecil"}], "q": [{"rep": 2, "q": "Fumador 40 años con disnea de medianos esfuerzos: ¿qué alteración confirma proceso obstructivo?", "a": "Relación VEF1/CVF disminuida", "e": "Relación VEF1/CVF baja. CVF baja o CPT baja sugieren restricción."}, {"rep": 2, "q": "¿Cómo se confirmaría el dx de EPOC?", "a": "Curva de flujo-volumen y volumen-tiempo", "e": "EPOC se confirma con espirometría (relación post-BD <0.70)."}]}, {"title": "Broncodilatador y DLCO", "html": "<div class=\"bar\">Respuesta al broncodilatador</div><ul><li>Salbutamol o ipratropio; 2–4 inhalaciones</li><li>Positiva si VEF1 o CVF sube <span class=\"ex\"><span class=\"m2\">≥ 12 %</span></span> y <span class=\"ex\"><span class=\"m2\">≥ 200 mL</span></span></li><li><span class=\"ex\">Asma: reversible</span>; <b>enfermedad pulmonar obstructiva crónica (EPOC)</b>: no reversible</li></ul><div class=\"box l\"><span class=\"ex\">Antes: VEF1 65 %, CVF 52 %, cociente 0.62. Después: 68 %, 58 %, 0.65 → obstrucción no reversible</span></div><div class=\"bar\">Difusión de CO (DLCO)</div><ul><li>Mide el intercambio gaseoso: se inspira CO con helio y se aguanta 10 s</li><li><span class=\"ex\"><span class=\"m\">Prueba más sensible y específica de enfermedad intersticial</span></span>; la mejor para pronóstico y seguimiento</li><li><span class=\"m2\">↓</span>: enfisema, intersticial, vascular pulmonar</li><li><span class=\"m2\">↑</span>: asma, obesidad, policitemia, hemorragia alveolar</li></ul><div class=\"bar\">Corazón y espirometría</div><ul><li>Cociente ↓: llenado izquierdo bajo</li><li>CVF ↓ con cociente normal: disfunción diastólica</li></ul>", "book": [{"pn": "523", "k": 19, "img": "img/t1-s04-p019.jpg", "fuente": "Cecil"}, {"pn": "524", "k": 20, "img": "img/t1-s04-p020.jpg", "fuente": "Cecil"}], "q": [{"rep": 3, "q": "¿Cuál es el estudio más específico (limitación y reversibilidad del flujo aéreo)?", "a": "Espirometría", "e": "Documenta obstrucción y reversibilidad (tema asma, lo incluyo por la espirometría)."}, {"rep": 2, "q": "Prueba fisiológica más sensible y específica para EID / indicación de DLCO:", "a": "Prueba de difusión de monóxido de carbono", "e": "DLCO cae precozmente en fibrosis, EID y enfermedad vascular pulmonar."}, {"rep": 1, "q": "Hombre 53 años, disnea progresiva, síndrome de rarefacción. ¿Estudio para confirmar?", "a": "Espirometría simple y con broncodilatador", "e": "Confirma obstrucción y reversibilidad."}]}, {"title": "Patrón obstructivo", "html": "<div class=\"bar bo\">Patrón obstructivo</div><ul><li><span class=\"o\">VEF1/CVF ↓</span> · es la clave</li><li><b>VR</b> y <b>CPT ↑</b> · atrapamiento aéreo</li><li>CPT <span class=\"m2\">> 125–130 %</span> = <b>hiperinsuflación</b></li><li>DLCO ↓ → enfisema; normal → asma o bronquitis</li></ul><div class=\"fig\"><svg viewBox=\"0 0 220 128\" width=\"220\" height=\"128\"><path d=\"M20 62H206M20 62V4\" stroke=\"#14212e\" stroke-width=\"1.3\"/>\n<path d=\"M24 62C26 26 30 8 40 8C80 22 130 48 172 62C160 104 50 104 24 62Z\" fill=\"none\" stroke=\"#5f6b78\" stroke-width=\"2.2\"/>\n<path d=\"M24 62C26 42 30 28 36 28C46 44 70 54 110 56C150 58 180 60 190 62C180 92 70 92 24 62Z\" fill=\"none\" stroke=\"#6a4cb0\" stroke-width=\"2.4\"/>\n<path d=\"M40 62C42 24 48 6 58 6C90 18 120 44 140 62C130 86 56 86 40 62Z\" fill=\"none\" stroke=\"#3f8a55\" stroke-width=\"2.4\"/>\n<g font-family=\"Geist,sans-serif\" font-weight=\"600\" font-size=\"10.5\"><text x=\"146\" y=\"14\" fill=\"#5f6b78\">Normal</text><text x=\"146\" y=\"28\" fill=\"#6a4cb0\">Obstructivo</text><text x=\"146\" y=\"42\" fill=\"#3f8a55\">Restrictivo</text>\n<text x=\"2\" y=\"78\" fill=\"#14212e\" font-size=\"9\">CPT</text><text x=\"193\" y=\"78\" fill=\"#14212e\" font-size=\"9\">VR</text>\n<text x=\"2\" y=\"124\" fill=\"#5f6b78\" font-size=\"9.5\">Flujo ↑</text><text x=\"150\" y=\"124\" fill=\"#5f6b78\" font-size=\"9.5\">Volumen →</text></g></svg></div><div class=\"bar bo\">Obstrucción de vía central</div><div class=\"t\"><div class=\"r\"><b>Fija</b> (estenosis traqueal) · flujo ↓ al inspirar y al espirar</div><div class=\"r\"><b>Extratorácica variable</b> · se aplana la <b>inspiración</b></div><div class=\"r\"><b>Intratorácica variable</b> · se aplana la espiración</div></div><p><span class=\"soft\">Se confunden con EPOC, pero tienen causa tratable.</span></p>", "book": [{"pn": "525", "k": 21, "img": "img/t1-s05-p021.jpg", "fuente": "Cecil"}], "q": []}, {"title": "Gravedad y GOLD", "html": "<div class=\"bar\">Lo que más preguntan</div><div class=\"t\"><div class=\"r\"><b>Dx de obstrucción</b> · <span class=\"ex\"><span class=\"m\">cociente VEF1/CVF</span></span></div><div class=\"r\"><b>Gravedad de la obstrucción</b> · <span class=\"ex\"><span class=\"m\">VEF1</span></span></div><div class=\"r\"><b>Sospecha de restricción</b> · <span class=\"ex\"><span class=\"m\">CVF ↓</span></span></div><div class=\"r\"><b>Confirma restricción</b> · <span class=\"ex\"><span class=\"m\">CPT ↓</span></span></div><div class=\"r\"><b>Reversibilidad</b> · VEF1 o CVF <span class=\"ex\"><span class=\"m\">≥ 12 % y 200 mL</span></span></div></div><div class=\"bar bo\">Gravedad por VEF1</div><div class=\"t\"><div class=\"r\"><b>&gt; 70 %</b> · leve</div><div class=\"r\"><b>60–69 %</b> · moderada</div><div class=\"r\"><b>50–59 %</b> · moderadamente grave</div><div class=\"r\"><b>35–49 %</b> · grave</div><div class=\"r\"><b>&lt; 35 %</b> · muy grave</div></div><div class=\"bar bo\">EPOC · estadios GOLD</div><p>Con VEF1/CVF <span class=\"m2\">< 0.7</span> <b>posbroncodilatador</b>:</p><div class=\"t\"><div class=\"r\"><b>I leve</b> · VEF1 ≥ 80 %</div><div class=\"r\"><b>II moderada</b> · <span class=\"ex\">50–79 %</span></div><div class=\"r\"><b>III grave</b> · 30–49 %</div><div class=\"r\"><b>IV muy grave</b> · <span class=\"ex\">&lt; 30 %</span></div></div><div class=\"box l\"><span class=\"ex\">Examen: VEF1 52 %, CVF 70 %, cociente 63 % → GOLD 2</span></div>", "book": [], "q": []}, {"title": "Patrón restrictivo", "html": "<div class=\"bar br\">Patrón restrictivo</div><ul><li><span class=\"rs\">CVF ↓ y VEF1 ↓</span> con cociente <b>normal o ↑</b></li><li>Curva <b>«sombrero de bruja»</b>: alta y picuda</li><li><span class=\"m\">Se confirma con CPT ↓</span></li><li>CPT normal = <span class=\"m\">inespecífico</span>; ≈ 50 % de los «restrictivos»</li></ul><div class=\"bar br\">Causas</div><div class=\"t\"><div class=\"r\"><b>Pulmón</b> · fibrosis y enfermedades intersticiales</div><div class=\"r\"><b>Fuera del pulmón</b> · obesidad, embarazo, derrame pleural, insuficiencia cardíaca, pared torácica, debilidad muscular</div></div><div class=\"bar br\">DLCO en restricción</div><ul><li>↓ en intersticial</li><li>Normal si la causa es extraparenquimatosa</li></ul><div class=\"box l\"><span class=\"ex\">Fibrosis pulmonar idiopática</span>: hipoxemia por <b>mayor grosor de la membrana alveolocapilar</b></div><p><span class=\"soft\">Gravedad: % de la CPT prevista.</span></p>", "book": [{"pn": "525", "k": 21, "img": "img/t1-s07-p021.jpg", "fuente": "Cecil"}, {"pn": "523", "k": 19, "img": "img/t1-s07-p019.jpg", "fuente": "Cecil"}], "q": [{"rep": 2, "q": "La enfermedad restrictiva se confirma por alteraciones en:", "a": "Capacidad pulmonar total", "e": "La CPT disminuida (pletismografía) confirma restricción."}, {"rep": 2, "q": "Cuál es el resultado más probable en la fisiología pulmonar (caso de neumonitis/fibrosis):", "a": "Espirometría con restricción", "e": "EID produce restricción con DLCO baja."}]}, {"title": "Cómo leer una espirometría", "html": "<div class=\"bar\">Comparación rápida</div><div class=\"t\"><div class=\"h c3\"><span>Medida</span><span class=\"h o2\">Obstr.</span><span class=\"h r2\">Restr.</span></div><div class=\"r c3\"><span>VEF1</span><span class=num>↓</span><span class=num>↓</span></div><div class=\"r c3\"><span>CVF</span><span class=num>N a ↓</span><span class=num>↓ a ↓↓</span></div><div class=\"r c3\"><span>VEF1/CVF</span><span class=num>↓</span><span class=num>N o ↑</span></div><div class=\"r c3\"><span>VR</span><span class=num>↑</span><span class=num>N o ↓</span></div><div class=\"r c3\"><span>CPT</span><span class=num>N a ↑↑</span><span class=num>↓ a ↓↓</span></div></div><p><span class=\"soft\">N = normal.</span></p><div class=\"bar\">Algoritmo de lectura</div><div class=\"t\"><div class=\"r\"><b>1</b> · Calidad y curva</div><div class=\"r\"><b>2</b> · VEF1/CVF <span class=\"m2\">↓</span> → <span class=\"o\">obstructivo</span></div><div class=\"r\"><b>3</b> · Cociente normal o ↑ con CVF ↓ → CPT: ↓ = <span class=\"rs\">restrictivo</span></div><div class=\"r\"><b>4</b> · Obstructivo con CVF ↓: CPT ↓ = <span class=\"m\">mixto</span></div><div class=\"r\"><b>5</b> · Broncodilatador y grado</div><div class=\"r\"><b>6</b> · DLCO: tipo de daño</div></div><p><span class=\"soft\">Dilución y lavado subestiman la CPT y pueden fingir un mixto.</span></p><div class=\"bar\">Otras pruebas de ventilación</div><ul><li><b>Ventilación voluntaria máxima (VVM)</b>: baja en debilidad; predice complicaciones postoperatorias</li><li><b>Presiones máximas (PIM/PEM)</b>: debilidad muscular</li></ul>", "book": [{"pn": "524", "k": 20, "img": "img/t1-s08-p020.jpg", "fuente": "Cecil"}, {"pn": "523", "k": 19, "img": "img/t1-s08-p019.jpg", "fuente": "Cecil"}], "q": []}, {"title": "Radiografía de tórax: lo básico", "html": "<div class=\"bar\">Radiografía de tórax</div><ul><li><span class=\"ex\">Estudio de imagen de elección en neumología</span></li><li><b>Posteroanterior (PA) + lateral</b>, tubo a 2 m; dosis ≈ <span class=num>0.1 mSv</span></li><li><span class=\"ex\">Inspiración completa = 10 costillas posteriores</span></li><li>Hilio normal ≤ <span class=\"ex\">16 mm</span></li></ul><div class=\"bar\">Silueta cardíaca</div><div class=\"fig\"><svg viewBox=\"0 0 220 124\" width=\"220\" height=\"124\"><rect x=\"14\" y=\"6\" width=\"192\" height=\"80\" rx=\"30\" fill=\"none\" stroke=\"#8a97a6\" stroke-width=\"2\"/>\n<ellipse cx=\"62\" cy=\"46\" rx=\"36\" ry=\"30\" fill=\"#e6edf5\"/><ellipse cx=\"158\" cy=\"46\" rx=\"36\" ry=\"30\" fill=\"#e6edf5\"/>\n<path d=\"M110 8V84\" stroke=\"#a9b4c0\" stroke-dasharray=\"3 3\"/>\n<ellipse cx=\"122\" cy=\"52\" rx=\"38\" ry=\"25\" fill=\"#f4b9c1\" fill-opacity=\".9\" stroke=\"#9c1f3a\" stroke-width=\"1.6\"/>\n<g stroke=\"#9c1f3a\" stroke-width=\"1.4\"><path d=\"M84 96H160M84 92V100M160 92V100\"/></g><g stroke=\"#14212e\" stroke-width=\"1.3\"><path d=\"M14 108H206M14 104V112M206 104V112\"/></g>\n<g font-family=\"Geist,sans-serif\" font-weight=\"600\" font-size=\"10\" text-anchor=\"middle\"><text x=\"122\" y=\"55\" fill=\"#9c1f3a\">corazón</text><text x=\"122\" y=\"95\" fill=\"#9c1f3a\" font-size=\"0\"> </text><text x=\"76\" y=\"92\" fill=\"#9c1f3a\" text-anchor=\"end\" font-size=\"10\">A</text><text x=\"110\" y=\"122\" fill=\"#14212e\">B · ICT = A/B &lt; 0.5</text></g></svg></div><ul><li><span class=\"ex\">Cardiomegalia: corazón &gt; ½ del tórax</span></li><li>De cabecera (<b>anteroposterior</b>, AP) agranda el corazón; en decúbito se esconde el derrame</li></ul><div class=\"bar\">Neumotórax</div><ul><li><span class=\"ex\">Línea fina de pleura visceral sin trama vascular</span> más allá</li><li>A tensión: mediastino <b>desviado al lado contrario</b> y diafragma aplanado</li><li><span class=\"m\">Urgencia clínica</span>: se trata antes de la placa si hay inestabilidad</li></ul>", "book": [{"pn": "519", "k": 15, "img": "img/t1-s09-p015.jpg", "fuente": "Cecil"}], "q": [{"rep": 2, "q": "Señale lo falso sobre la tele de tórax:", "a": "Es el estudio de elección para patología mediastinal", "e": "La TAC es de elección en mediastino; la Rx es tamizaje."}, {"rep": 1, "q": "Inspiración completa en Rx se identifica por:", "a": "10 costillas posteriores", "e": "Es control de calidad."}]}, {"title": "Alveolar, atelectasia y derrame", "html": "<div class=\"bar\">Patrón alveolar</div><ul><li><span class=\"ex\"><span class=\"m\">Broncograma aéreo</span></span> = signo clave</li><li>Nódulos acinares, vidrio esmerilado, consolidación lobar o segmentaria</li></ul><div class=\"t\"><div class=\"r\"><b>Neumonía bacteriana típica</b> · <span class=\"ex\">infiltrado alveolar</span></div><div class=\"r\"><b>Lobar con atelectasia</b> · obstrucción bronquial</div><div class=\"r\"><b>Perihiliar</b> · edema, hemorragia</div></div><div class=\"bar\">Atelectasia y derrame</div><div class=\"t\"><div class=\"r\"><b>Atelectasia</b> · <span class=\"ex\">tráquea desviada hacia el lado de la lesión</span></div><div class=\"r\"><b>Derrame</b> · <span class=\"ex\">signo del menisco</span>; desplaza el mediastino al lado sano</div><div class=\"r\"><b>Paraneumónico</b> · confirmar con <span class=\"ex\">decúbito lateral con rayo horizontal</span></div></div><div class=\"bar\">Signo de la silueta</div><ul><li>Una lesión del <b>mismo grosor</b> que el borde vecino lo borra</li><li>Borra borde cardíaco derecho → lóbulo medio; izquierdo → língula</li><li>Borra el hemidiafragma → lóbulo inferior</li></ul>", "book": [{"pn": "514", "k": 10, "img": "img/t1-s10-p010.jpg", "fuente": "Cecil"}, {"pn": "515", "k": 11, "img": "img/t1-s10-p011.jpg", "fuente": "Cecil"}], "q": [{"rep": 2, "q": "De la Rx de tórax normal, la verdadera:", "a": "La vena cava superior está en el borde mediastinal derecho", "e": "Borde derecho: VCS y aurícula derecha. Arco aórtico, tronco y orejuela izquierda están a la izquierda."}, {"rep": 2, "q": "De la Rx patológica, la verdadera:", "a": "La tuberculosis es causa frecuente de infiltrado cavitado", "e": "Derrame/neumotórax empujan lejos; atelectasia jala hacia el lado afectado; el edema es bilateral."}, {"rep": 2, "q": "Signo radiológico patognomónico del infiltrado alveolar:", "a": "Broncograma aéreo", "e": "Bronquios con aire dentro de alvéolos ocupados."}]}, {"title": "Patrón intersticial y edema", "html": "<div class=\"bar\">Patrón intersticial</div><div class=\"t\"><div class=\"r\"><b>Micronodular</b> · ≤ 1 mm: TB miliar, silicosis</div><div class=\"r\"><b>Nodular</b> · hasta 1 cm</div><div class=\"r\"><b>Reticular</b> · malla: edema, atípica, esclerodermia, asbestosis</div><div class=\"r\"><b>Panal</b> · <span class=\"ex\">vidrio despulido o panalización</span> = fibrosis; <span class=\"m\">terminal</span></div></div><div class=\"box l\"><span class=\"ex\"><span class=\"m\">Cáscara de huevo</span></span> (ganglios) → <b>silicosis</b></div><div class=\"bar\">Edema cardiogénico y Kerley</div><ul><li><span class=\"ex\">Cardiomegalia, ↑ trama vascular, hilios anchos y líneas de Kerley</span></li></ul><div class=\"t\"><div class=\"r\"><b>A</b> · 2–4 cm desde el hilio</div><div class=\"r\"><b>B</b> · 1 cm en base; <span class=\"m\">insuficiencia cardíaca</span></div><div class=\"r\"><b>C</b> · patrón reticular</div></div><p><span class=\"soft\">A y B se ven en el edema de pulmón.</span></p>", "book": [{"pn": "515", "k": 11, "img": "img/t1-s11-p011.jpg", "fuente": "Cecil"}], "q": [{"rep": 3, "q": "Ver en una Rx de tórax cáscara de huevo, ¿con cuál enfermedad es compatible?", "a": "Silicosis", "e": "Calcificación periférica de ganglios hiliares = silicosis. Asbestosis da placas pleurales."}, {"rep": 1, "q": "Datos de edema pulmonar cardiogénico en Rx:", "a": "Cardiomegalia, trama vascular aumentada, hilios >16 mm y líneas de Kerley", "e": "Kerley B = septos engrosados por líquido."}, {"rep": 1, "q": "Signo típico de fibrosis pulmonar:", "a": "Vidrio despulido o panalización", "e": "Patrón intersticial crónico."}]}, {"title": "Vasos, TB, enfisema y otras técnicas", "html": "<div class=\"bar\">Vasos y volumen</div><div class=\"t\"><div class=\"r\"><b>Cefalización</b> · insuficiencia cardíaca izquierda, mitral</div><div class=\"r\"><b>Igualamiento</b> · anemia, obesidad, embarazo</div><div class=\"r\"><b>Oligohemia</b> · hipovolemia, enfisema</div><div class=\"r\"><b>Centralización</b> · hipertensión pulmonar</div></div><div class=\"bar\">Tuberculosis en la placa</div><ul><li><b>Primoinfección</b>: complejo de Ghon (nódulo + adenopatía hiliar)</li><li><b>Reactivación</b>: <span class=\"ex\">ápices y cavitación</span></li></ul><div class=\"bar\">Enfisema y bronquiectasias</div><ul><li><span class=\"ex\">Hiperinflación</span>: pulmones oscuros, diafragma plano</li><li>Corazón vertical y estrecho</li><li>Bronquiectasias: <span class=\"ex\">tomografía de alta resolución (TCAR)</span> con dilataciones hasta la periferia</li></ul><div class=\"bar\">Otras técnicas</div><ul><li><b>Tomografía computarizada (TC)</b>: sin superposición</li><li><b>Ecografía</b>: derrame, neumotórax; guía toracocentesis</li></ul>", "book": [{"pn": "515", "k": 11, "img": "img/t1-s12-p011.jpg", "fuente": "Cecil"}, {"pn": "516", "k": 12, "img": "img/t1-s12-p012.jpg", "fuente": "Cecil"}], "q": []}], "top": [{"rep": 5, "q": "Se define como respuesta significativa al broncodilatador:", "a": "Incremento en el FEV1 o FVC >12% y 200 ml", "e": "Criterio ATS/ERS: aumento >12% y >200 ml. Cumplir solo uno de los dos criterios o exigir ambos parámetros no está validado."}, {"rep": 3, "q": "El número de maniobras de CVF que debe realizar el paciente en una espirometría no debe ser mayor de:", "a": "8 maniobras", "e": "Máximo 8 intentos por fatiga; con 3 aceptables y reproducibles basta."}, {"rep": 3, "q": "Ver en una Rx de tórax cáscara de huevo, ¿con cuál enfermedad es compatible?", "a": "Silicosis", "e": "Calcificación periférica de ganglios hiliares = silicosis. Asbestosis da placas pleurales."}, {"rep": 3, "q": "¿Qué valor establece el diagnóstico de obstrucción? (EPOC en fumador)", "a": "Relación VEF1/CVF", "e": "Obstrucción = relación VEF1/CVF disminuida (<0.70 o <LIN). VEF1 mide gravedad."}, {"rep": 3, "q": "¿Cuál es el estudio más específico (limitación y reversibilidad del flujo aéreo)?", "a": "Espirometría", "e": "Documenta obstrucción y reversibilidad (tema asma, lo incluyo por la espirometría)."}, {"rep": 2, "q": "Fumador 40 años con disnea de medianos esfuerzos: ¿qué alteración confirma proceso obstructivo?", "a": "Relación VEF1/CVF disminuida", "e": "Relación VEF1/CVF baja. CVF baja o CPT baja sugieren restricción."}, {"rep": 2, "q": "¿Qué parámetro indica la severidad de la obstrucción?", "a": "Volumen espiratorio forzado en el 1er segundo", "e": "El VEF1 (% del predicho) gradúa la gravedad; la relación solo diagnostica."}, {"rep": 2, "q": "El diagnóstico espirométrico de restricción se sospecha por alteraciones en:", "a": "Capacidad vital forzada", "e": "CVF baja con relación normal/alta sugiere restricción; la confirmación requiere CPT."}]}, {"name": "Infecciones de vías respiratorias superiores, neumonía y SARS-CoV-2", "tab": "Tema 2", "slides": [{"title": "Vías aéreas superiores", "html": "<div class=\"bar\">Vías aéreas superiores</div><ul><li><b>Resfriado común</b>: <span class=\"m\">rinovirus</span> (el más frecuente); autolimitado 7–10 d</li><li>Tratamiento solo sintomático; <b>no</b> antibióticos</li><li><b>Faringoamigdalitis</b>: casi siempre viral; bacteriana = <span class=\"m\">Streptococcus pyogenes</span> (estreptococo del grupo A, EGA)</li><li><b>Criterios de Centor</b> (1 punto c/u): fiebre, exudado amigdalino, adenopatía cervical anterior dolorosa, <b>sin tos</b></li></ul><div class=\"bar\">Qué hacer con el Centor</div><ul><li>0–1: no se trata ni se prueba</li><li>2–3: prueba rápida de antígeno o cultivo</li><li>≥4: se puede tratar de inicio; <span class=\"ex\">prueba rápida con alta especificidad</span></li><li>Tratamiento: <span class=\"m\">penicilina V o amoxicilina 10 d</span>; o penicilina G benzatínica IM dosis única</li><li>Alergia: macrólido o clindamicina</li></ul><div class=\"bar\">Complicaciones del EGA</div><ul><li><span class=\"m2\">Fiebre reumática</span>: el antibiótico <b>sí</b> la previene</li><li><b>Glomerulonefritis postestreptocócica</b>: el antibiótico <b>no</b> la previene</li><li><b>Absceso periamigdalino</b>: trismo, voz «de papa caliente», úvula desviada; drenaje + antibiótico</li><li><b>Mononucleosis (virus de Epstein-Barr, VEB)</b>: exudado, adenopatía posterior, esplenomegalia; <span class=\"m\">amoxicilina causa exantema</span></li><li><b>Difteria</b>: pseudomembrana gris adherida</li></ul>", "book": [], "q": [{"rep": 4, "q": "¿Cuál es el principal parámetro en un derrame paraneumónico que determina complicación y necesidad de drenaje pleural?", "a": "pH ácido", "e": "pH <7.2 es el criterio principal de drenaje. La glucosa estaría baja (no alta); proteínas y DHL altas son solo de exudado. Nota: f02 c2#43 da 'glucosa baja' como respuesta."}, {"rep": 4, "q": "¿Cuál de los siguientes enunciados es correcto en relación a absceso pulmonar?", "a": "Los anaerobios de la boca y faringe son los patógenos más frecuentes", "e": "El origen es microaspiración de flora anaerobia oral. El esputo se contamina, no es útil; la vía hematógena es poco común."}, {"rep": 3, "q": "Líquido pleural turbio/ pH 7.15, DHL 1200 UI (cociente DHL pleura/plasma 1.2), glucosa <40, Gram positivo. ¿Siguiente paso?", "a": "Colocar sonda de pleurostomía e iniciar antibióticos de amplio espectro", "e": "Derrame complicado requiere drenaje más antibiótico. Solo antibiótico es insuficiente y la toracoscopia se reserva si falla el drenaje."}]}, {"title": "Sinusitis aguda", "html": "<div class=\"bar\">Sinusitis aguda</div><ul><li>Casi siempre viral</li><li>Sospechar bacteriana si: <span class=\"m\">>10 días</span> sin mejoría, fiebre ≥39 °C con secreción purulenta ≥3–4 d, o «doble empeoramiento»</li><li>Bacterias: <b>S. pneumoniae</b>, <b>H. influenzae</b>, <b>M. catarrhalis</b></li><li>Tratamiento: amoxicilina-clavulanato; lavados nasales y esteroide nasal</li><li>Crónica: >12 semanas</li><li><span class=\"m2\">Complicación temida</span>: celulitis orbitaria y trombosis del seno cavernoso</li></ul>", "book": [], "q": []}, {"title": "Influenza", "html": "<div class=\"bar\">Influenza</div><ul><li>Virus A y B; inicio súbito: fiebre alta, mialgias, cefalea, tos seca</li><li>Etiología más probable en cuadro febril de 72 h con mialgias en adulto mayor: <span class=\"ex\">influenza A</span></li><li>Diagnóstico rápido y confiable: <span class=\"m\">RT-PCR de exudado faríngeo</span></li><li>Prueba rápida de antígeno: específica pero poco sensible</li><li>Tratamiento: <span class=\"m\">oseltamivir</span> (inhibidor de neuraminidasa) 5 d; ideal en <48 h; en graves y hospitalizados aunque pasen 48 h</li><li>Amantadina ya no se usa (resistencia)</li></ul><div class=\"bar\">Complicaciones y prevención</div><ul><li>Neumonía bacteriana secundaria: <span class=\"m\">S. aureus</span> y neumococo</li><li>Neumonía viral primaria: grave, hipoxemia</li><li>Vacuna anual a todos; prioridad en ≥65 años, embarazadas, EPOC</li></ul>", "book": [{"pn": "598", "k": 101, "img": "img/t2-s03-p101.jpg", "fuente": "Cecil"}, {"pn": "595", "k": 98, "img": "img/t2-s03-p098.jpg", "fuente": "Cecil"}], "q": [{"rep": 4, "q": "Hombre de 68 años con cardiopatía isquémica, 72 h con fiebre 39°C, mialgias, odinofagia, rinorrea hialina, tos irritativa e hiperemia faríngea. ¿Agente etiológico más probable?", "a": "Virus influenza A", "e": "Fiebre alta, mialgias y artralgias de inicio agudo orientan a influenza A; rinovirus y VSR dan cuadros catarrales más leves."}, {"rep": 4, "q": "En el caso anterior, ¿cómo confirmaría de forma rápida y con adecuada sensibilidad y especificidad el diagnóstico?", "a": "PCR en tiempo real en exudado faríngeo", "e": "La RT-PCR es el estándar. La prueba rápida es poco sensible; la serología no sirve en fase aguda y no hay antigenuria."}, {"rep": 4, "q": "¿Cómo trataría la infección por este virus?", "a": "Oseltamivir", "e": "Oseltamivir (inhibidor de neuraminidasa) idealmente en las primeras 48 h. Los demás antivirales no actúan sobre influenza."}]}, {"title": "Neumonía: definición y mecanismo", "html": "<div class=\"bar\">Neumonía: qué es</div><ul><li>Infección del parénquima con infiltrado nuevo en la radiografía</li><li><b>Neumonía adquirida en la comunidad (NAC)</b>: fuera del hospital</li><li><b>Neumonía intrahospitalaria (NIH)</b>: ≥48 h tras el ingreso</li><li><b>Neumonía asociada a ventilador (NAV)</b>: ≥48 h tras intubar</li><li>Mecanismo más frecuente: <span class=\"m\">microaspiración de la orofaringe</span></li><li>Otras vías: inhalación, hematógena, contigüidad</li></ul><div class=\"bar\">Resistencia del neumococo</div><ul><li>Riesgo: edad extrema, β-lactámico en 3 meses, alcoholismo, comorbilidad, inmunosupresión, guardería</li><li><span class=\"soft\">Residir en asilo no es el factor clásico</span></li></ul>", "book": [{"pn": "603", "k": 106, "img": "img/t2-s04-p106.jpg", "fuente": "Cecil"}, {"pn": "594", "k": 97, "img": "img/t2-s04-p097.jpg", "fuente": "Cecil"}], "q": [{"rep": 2, "q": "Mecanismo de infección más frecuente en NAC.", "a": "Microaspiración del contenido de la orofaringe", "e": "La microaspiración orofaríngea es el mecanismo principal; la inhalación aplica a atípicos/TB, y la aspiración masiva gástrica es poco frecuente."}, {"rep": 2, "q": "Factor de riesgo para neumococo drogorresistente.", "a": "Alcoholismo", "e": "ATS/IDSA lista alcoholismo, edad >65, beta-lactámico reciente, inmunosupresión y comorbilidades. Respuesta dudosa: 'residente de asilo' también es plausible."}]}, {"title": "Etiología de la NAC", "html": "<div class=\"bar\">Etiología de la NAC</div><ul><li><b>Germen más común: <span class=\"m\">neumococo</span></b> (Streptococcus pneumoniae)</li><li>Ambulatorio: neumococo, <b>Mycoplasma pneumoniae</b>, H. influenzae, Chlamydia pneumoniae, virus</li><li>Hospitalizado: + <b>Legionella</b> y aspiración</li><li>UCI: neumococo, Legionella, H. influenzae, bacilos gram negativos, S. aureus</li><li><span class=\"ex\">Colonizador de enfermedad pulmonar estructural: Pseudomonas aeruginosa</span></li></ul><div class=\"bar\">Pistas clínicas</div><ul><li><b>Alcohólico</b>: Klebsiella («jalea de grosella») y aspiración</li><li><b>EPOC</b>: H. influenzae y Moraxella</li><li><b>Posinfluenza</b>: Staphylococcus aureus</li><li><b>Bronquiectasias, fibrosis quística</b>: Pseudomonas</li><li><b>Mycoplasma</b>: joven, tos seca, anemia hemolítica por crioaglutininas</li><li><b>Legionella</b>: hiponatremia, diarrea, agua o aire acondicionado</li></ul>", "book": [{"pn": "598", "k": 101, "img": "img/t2-s05-p101.jpg", "fuente": "Cecil"}], "q": [{"rep": 5, "q": "¿Cuál es el germen bacteriano que más comúnmente causa neumonía adquirida en la comunidad?", "a": "Neumococo", "e": "Streptococcus pneumoniae es el más frecuente en NAC; Legionella, Chlamydia y S. aureus son menos comunes."}, {"rep": 3, "q": "Masculino de 65 años con bronquitis crónica y alcoholismo, tos productiva abundante, fiebre y pérdida de peso; Rx con nivel hidroaéreo. ¿Probable dx?", "a": "Absceso pulmonar", "e": "Cavidad con nivel hidroaéreo en un alcohólico es absceso por aspiración. Hidroneumotórax es pleural (nivel que cruza todo el hemitórax) y el empiema no cavita el parénquima."}, {"rep": 2, "q": "Estudiante de 22 años con tos irritativa, fiebre 38.5°C 5 días, estertores en base derecha e infiltrado alveolar LID. ¿Agentes más probables?", "a": "S. pneumoniae y Mycoplasma pneumoniae", "e": "En joven sano ambulatorio predominan neumococo y atípicos. Pseudomonas, Klebsiella y TB no son lo habitual."}]}, {"title": "Clínica y diagnóstico", "html": "<div class=\"bar\">Clínica y exploración</div><ul><li>Fiebre, tos con esputo purulento, disnea, dolor pleurítico</li><li><span class=\"m\">Síndrome de consolidación</span>: estertores crepitantes, soplo tubario, matidez, ↑ vibraciones vocales</li><li>Atípica: tos seca, síntomas extrapulmonares, exploración pobre</li></ul><div class=\"bar\">Radiografía y diagnóstico</div><ul><li>Neumonía bacteriana típica: <span class=\"m\">infiltrado alveolar</span> con broncograma aéreo</li><li>Atípica o viral: infiltrado intersticial</li><li><span class=\"ex\">La radiografía de tórax es lo primero que se pide al ingresar</span></li><li>Hospitalizados: hemocultivos, cultivo de esputo, antígeno urinario (neumococo y Legionella)</li><li><span class=\"m2\">Toracocentesis</span>: solo si hay derrame; no de rutina</li><li><b>Procalcitonina</b>: ayuda a suspender el antibiótico</li></ul>", "book": [{"pn": "596", "k": 99, "img": "img/t2-s06-p099.jpg", "fuente": "Cecil"}, {"pn": "595", "k": 98, "img": "img/t2-s06-p098.jpg", "fuente": "Cecil"}], "q": [{"rep": 3, "q": "¿Cuál es la manifestación radiológica de una neumonía bacteriana típica?", "a": "Infiltrado alveolar", "e": "La típica produce consolidación alveolar lobar; el intersticial/reticular corresponde a atípicas y virus."}, {"rep": 3, "q": "Masc de 38 años con fiebre, tos mucopurulenta, disnea y dolor torácico, matidez basal derecha y opacidad con infiltrado alveolar, leucocitos 16,800. Con signo del menisco, ¿cuál es el siguiente paso?", "a": "Rx en decúbito lateral derecho con rayo horizontal", "e": "Confirma líquido libre (>10 mm de lámina) antes de puncionar. La TAC es posterior y el antibiótico no sustituye caracterizar el derrame."}, {"rep": 2, "q": "Masc 43 años con fiebre vespertina, tos mucopurulenta, esputo hemoptoico, síndrome de derrame pleural izquierdo tras ceftriaxona sin mejoría. ¿Dx?", "a": "Derrame paraneumónico", "e": "Fiebre, tos purulenta y derrame en contexto de neumonía = paraneumónico. Los demás no explican el cuadro agudo infeccioso."}]}, {"title": "Gravedad: CURB-65, Fine, ATS/IDSA", "html": "<div class=\"bar\">CURB-65</div><ul><li><span class=\"m\">C</span>onfusión · <span class=\"m\">U</span>rea >7 mmol/L · <span class=\"m\">R</span>espiración ≥30/min · <span class=\"m\">B</span>aja presión (<90/60) · edad ≥<span class=\"m\">65</span></li><li><b>0–1</b> ambulatorio · <b>2</b> hospital · <b>≥3</b> grave, valorar UCI</li><li><span class=\"ex\">Es la escala que describe mejor la gravedad de la NAC</span></li></ul><div class=\"bar\">Índice de Fine (PORT)</div><ul><li>Clases I–V; <b>I–II</b> ambulatorio, <b>III</b> observación, <b>IV–V</b> hospital</li><li><span class=\"ex\">Sugiere la seguridad del tratamiento ambulatorio</span> en clase I (<50 años, sin comorbilidad)</li></ul><div class=\"bar\">Criterios ATS/IDSA de NAC grave</div><ul><li><b>Mayores</b> (basta 1): <span class=\"m2\">ventilación mecánica</span> o choque séptico con vasopresor</li><li><b>Menores</b> (≥3): FR ≥30, PaO₂/FiO₂ ≤250, multilobar, confusión, urea alta, leucopenia, plaquetas <100 mil, hipotermia, hipotensión</li><li>Con criterios → <b>UCI</b></li></ul>", "book": [], "q": [{"rep": 3, "q": "¿Cuál es el tx más adecuado de una neumonía con un punto en la escala CURB-65?", "a": "Claritromicina", "e": "CURB 0-1 se maneja ambulatorio con macrólido. Ceftriaxona es para hospitalizados y ciprofloxacino no cubre bien neumococo."}, {"rep": 2, "q": "¿Qué escala sugiere la seguridad del tratamiento ambulatorio si el paciente es clase I?", "a": "Port y Fine", "e": "Las 'clases I-V' son de PORT/Fine (PSI); la clase I es de bajo riesgo. Murray y Kirby miden lesión pulmonar/oxigenación."}, {"rep": 2, "q": "¿Qué escala describiría mejor la gravedad en NAC?", "a": "E) CURB-65", "e": "CURB-65 es la escala clínica sencilla de gravedad/sitio de manejo. Las otras no se usan para NAC."}]}, {"title": "Tratamiento empírico de la NAC", "html": "<div class=\"bar\">Tratamiento empírico de la NAC</div><ul><li><b>Ambulatorio sano</b>: <span class=\"m\">amoxicilina</span> (o doxiciclina o macrólido)</li><li><b>Ambulatorio con comorbilidad</b>: amoxicilina-clavulanato + macrólido o doxiciclina; o <span class=\"m\">fluoroquinolona respiratoria</span> sola</li><li><b>Hospital sala</b>: β-lactámico (ceftriaxona) + macrólido, o fluoroquinolona respiratoria</li><li><b>UCI</b>: <span class=\"m\">ceftriaxona + macrólido o fluoroquinolona</span></li><li><span class=\"m2\">Si hay riesgo de Pseudomonas</span>: β-lactámico antipseudomonas (piperacilina-tazobactam, cefepime, meropenem) + fluoroquinolona</li><li>Riesgo de MRSA: agregar vancomicina o linezolid</li></ul>", "book": [{"pn": "600", "k": 103, "img": "img/t2-s08-p103.jpg", "fuente": "Cecil"}, {"pn": "601", "k": 104, "img": "img/t2-s08-p104.jpg", "fuente": "Cecil"}], "q": [{"rep": 2, "q": "¿Tratamiento empírico sugerido por ATS en el paciente intubado en UCI?", "a": "Cefalosporina 3ª sin cobertura antipseudomonas más fluoroquinolona respiratoria", "e": "Sin factores de riesgo para Pseudomonas, UCI: beta-lactámico (ceftriaxona) más fluoroquinolona/macrólido. Monoterapia o amoxi-clav son insuficientes; carbapenem es innecesario."}, {"rep": 2, "q": "Si decide iniciar antibiótico, el tratamiento sería:", "a": "Una fluoroquinolona respiratoria", "e": "Paciente admitida: fluoroquinolona respiratoria (o beta-lactámico más macrólido). Macrólido solo es ambulatorio y aminoglucósido no cubre neumococo."}, {"rep": 1, "q": "NAC en previamente sanos sin antibióticos en 3 meses:", "a": "Macrólido o quinolona respiratoria", "e": "Macrólidos o doxiciclina; quinolona respiratoria alternativa."}]}, {"title": "Atípicas, duración y evolución", "html": "<div class=\"bar\">Atípicas: qué sí sirve</div><ul><li><span class=\"m\">Macrólidos</span> (azitromicina, claritromicina, eritromicina), <b>doxiciclina</b> y <b>fluoroquinolonas</b></li><li><span class=\"m2\">Amoxicilina no sirve</span>: Mycoplasma no tiene pared celular</li><li>Legionella: antígeno urinario; levofloxacino o azitromicina</li><li>NAC grave: Legionella, neumococo, S. aureus y gram negativos; <b>no</b> es típico de Chlamydia</li></ul><div class=\"bar\">Duración y evolución</div><ul><li><span class=\"m\">Mínimo 5 días</span> y estabilidad clínica; pasar a vía oral cuando mejora (<b>tratamiento secuencial</b>)</li><li><span class=\"ex\">Pronóstico mejor si se da el antibiótico en las primeras 4 horas</span></li><li>Sin mejoría a las 72 h: revisar diagnóstico, resistencia o complicación</li><li>Radiografía de control en 6–8 semanas si es fumador o >50 años</li></ul>", "book": [{"pn": "601", "k": 104, "img": "img/t2-s09-p104.jpg", "fuente": "Cecil"}, {"pn": "600", "k": 103, "img": "img/t2-s09-p103.jpg", "fuente": "Cecil"}], "q": [{"rep": 2, "q": "Líquido pleural con pH 7.10, glucosa 32 mg/dl, LDH 1200 UI/L, Gram negativo. ¿Estrategia terapéutica?", "a": "Sonda de toracostomía más antibioticoterapia", "e": "Criterios de drenaje: pH<7.2, glucosa<40, LDH>1000. La sonda más antibiótico es el primer paso; fibrinolíticos o cirugía son para loculación o falla."}, {"rep": 2, "q": "Paciente del caso anterior: ¿medida más apropiada?", "a": "Azitromicina VO y manejo ambulatorio", "e": "Paciente estable (CURB-65 bajo) con macrólido ambulatorio. Aminoglucósido no cubre neumococo; el esquema doble es para grave; sin datos de TB."}, {"rep": 2, "q": "Paciente de 67 años con NAC. Las siguientes son incorrectas, excepto una (redacción inconsistente en la fuente).", "a": "El pronóstico es mejor si el tratamiento inicia en las primeras 4 horas", "e": "El tratamiento es empírico, los hemocultivos son poco sensibles, el esputo rara vez orienta y la terapia secuencial sí se aplica. Solo C es verdadera."}]}, {"title": "Complicaciones y prevención", "html": "<div class=\"bar\">Complicaciones</div><ul><li><b>Derrame paraneumónico</b>: estéril, en el contexto de neumonía; <span class=\"m\">empiema</span> = pus</li><li>Complicado si: <span class=\"m2\">pH <7.2, glucosa <60, LDH >1000</span> o cultivo positivo → drenar con sonda</li><li>Absceso pulmonar, SDRA, sepsis</li><li><span class=\"soft\">El quilotórax no es complicación de neumonía</span></li></ul><div class=\"bar\">Prevención</div><ul><li>Vacuna antineumocócica (PCV20, o PCV15 + PPSV23): ≥65 años y riesgo</li><li>Vacuna anual de influenza</li><li>Dejar de fumar</li></ul>", "book": [], "q": [{"rep": 3, "q": "Toracocentesis: líquido xantocrómico, pH 7.38, glucosa 67 mg/dl, DHL 245 UI, Gram negativo. ¿Dx?", "a": "Derrame paraneumónico no complicado", "e": "pH >7.2, glucosa >40-60, DHL <1000 y Gram negativo = no complicado. Complicado exigiría pH<7.2, glucosa baja o DHL >1000; empiema tiene pus."}, {"rep": 2, "q": "Paciente con NAC y derrame pleural puncionado. ¿Cuál es correcta?", "a": "Puede ser derrame paraneumónico: derrame pleural estéril que surge en contexto de neumonía", "e": "Paraneumónico = derrame estéril asociado a neumonía. Complicado ≠ hemotórax, empiema = pus, y el quilotórax no es complicación de NAC."}, {"rep": 1, "q": "Masculino de 55 años diabético, alcohólico, hospitalizado por absceso pulmonar; a las 24 h fiebre 40°C, hipotensión, hipoxemia y Rx con opacidad homogénea que borra todo el hemitórax derecho. ¿Dx?", "a": "Empiema y sepsis", "e": "La opacidad total con sepsis tras absceso corresponde a empiema por ruptura a pleura."}]}, {"title": "Neumonía asociada a ventilador", "html": "<div class=\"fig\"><svg viewBox=\"0 0 220 128\" width=\"220\" height=\"128\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><path id=\"lg\" d=\"M8 8C2 8 0 40 2 66C4 86 16 96 30 94C40 92 42 70 42 46C42 24 28 8 8 8Z\" /></defs>\n<g stroke=\"#5f7d99\" stroke-width=\"1.6\" fill=\"#eaf2fa\">\n<use href=\"#lg\" x=\"6\"/><use href=\"#lg\" x=\"82\"/><use href=\"#lg\" x=\"158\"/></g>\n<path d=\"M8 50C8 40 28 38 40 46L42 78C30 84 14 80 10 70Z\" fill=\"#e8590c\" fill-opacity=\".55\" stroke=\"none\" transform=\"translate(6,0)\"/>\n<g stroke=\"none\" fill=\"#6a4cb0\" fill-opacity=\".55\" transform=\"translate(82,0)\"><circle cx=\"16\" cy=\"30\" r=\"7\"/><circle cx=\"28\" cy=\"46\" r=\"8\"/><circle cx=\"14\" cy=\"62\" r=\"7\"/><circle cx=\"30\" cy=\"76\" r=\"6\"/><circle cx=\"20\" cy=\"46\" r=\"5\"/></g>\n<g stroke=\"#3f8a55\" stroke-width=\"1.4\" fill=\"none\" transform=\"translate(158,0)\"><path d=\"M6 24L36 30M5 38L38 44M5 52L38 58M6 66L36 72M8 80L30 84\"/><path d=\"M12 20L16 88M24 18L26 90\" stroke-opacity=\".5\"/></g>\n<g font-family=\"Geist,sans-serif\" font-weight=\"600\" font-size=\"11\" fill=\"#14212e\" text-anchor=\"middle\"><text x=\"28\" y=\"112\">Lobar</text><text x=\"104\" y=\"112\">Broncoalveolar</text><text x=\"180\" y=\"112\">Intersticial</text></g>\n<g font-family=\"Geist,sans-serif\" font-weight=\"600\" font-size=\"9.5\" fill=\"#5f6b78\" text-anchor=\"middle\"><text x=\"28\" y=\"124\">neumococo</text><text x=\"104\" y=\"124\">parches · Staph</text><text x=\"180\" y=\"124\">atípicas · virus</text></g>\n</svg></div><div class=\"bar\">Neumonía asociada a ventilador</div><ul><li>Con ventilación mecánica la incidencia <span class=\"m\">aumenta de 6 a 20 veces</span></li><li>Aumenta morbilidad y estancia; es una infección nosocomial frecuente</li><li>Agentes: S. aureus (MRSA), Pseudomonas, Klebsiella, Acinetobacter</li><li>Factor de riesgo de multirresistencia: <span class=\"m\">antibióticos IV en los 90 días previos</span></li><li>También: choque séptico, SDRA, ≥5 días de hospital, diálisis</li><li>Tratamiento: cubrir MRSA y Pseudomonas según riesgo; 7 días</li><li>Prevenir: cabecera 30–45°, mínima sedación, aspirar secreciones subglóticas</li></ul>", "book": [{"pn": "603", "k": 106, "img": "img/t2-s11-p106.jpg", "fuente": "Cecil"}], "q": [{"rep": 2, "q": "Neumonía asociada al ventilador, marque la respuesta correcta.", "a": "La incidencia se incrementa de 6 a 20 veces con la ventilación mecánica", "e": "La ventilación mecánica multiplica el riesgo 6-20 veces. La NAV prolonga estancia y morbimortalidad."}, {"rep": 2, "q": "Factor de riesgo para patógenos multidrogorresistentes en NAV:", "a": "Antibioticoterapia en los 90 días previos", "e": "Antibiótico IV en los 90 días previos es factor de MDR; la hospitalización debe ser >=5 días."}]}, {"title": "Aspiración y absceso", "html": "<div class=\"bar\">Aspiración y absceso</div><ul><li>Aspiración: segmento posterior del lóbulo superior y superior del inferior</li><li>Gérmenes: anaerobios de la boca</li><li>Absceso por broncoaspiración: <span class=\"m\">clindamicina y drenaje postural</span></li><li>Sonda o cirugía solo si empiema o falla</li><li>Neumonía en alcohólico o con disfagia: pensar en aspiración</li></ul>", "book": [{"pn": "603", "k": 106, "img": "img/t2-s12-p106.jpg", "fuente": "Cecil"}, {"pn": "596", "k": 99, "img": "img/t2-s12-p099.jpg", "fuente": "Cecil"}], "q": [{"rep": 5, "q": "¿Cuál es el tx más adecuado en un px con absceso pulmonar por broncoaspiración?", "a": "Clindamicina y drenaje postural", "e": "Los anaerobios orofaríngeos responden a clindamicina más drenaje postural. La broncoscopia, la lobectomía y la sonda son para fallas o complicaciones, no primera línea."}, {"rep": 4, "q": "Masculino de 25 años con crisis convulsivas desde la infancia, tos productiva abundante y fétida, imagen con nivel hidroaéreo; se dx absceso pulmonar. ¿Cuál es correcta?", "a": "El antibiótico de elección es clindamicina", "e": "La aspiración durante convulsiones favorece anaerobios orales; clindamicina es la elección. El esputo está contaminado por flora oral, Pseudomonas no predomina y la cirugía es excepcional (f02: terapia percusiva, drenaje postural y clindamicina)."}]}, {"title": "COVID-19: qué es y diagnóstico", "html": "<div class=\"bar\">COVID-19: qué es</div><ul><li><b>SARS-CoV-2</b>, virus ARN; entra por el receptor <b>ECA2</b></li><li>Incubación 2–14 días (media 5)</li><li>Fiebre, tos, disnea, mialgias, <b>anosmia y ageusia</b></li><li><span class=\"m\">Linfopenia</span>, ↑ DHL, ferritina, PCR y dímero D</li></ul><div class=\"bar\">Diagnóstico</div><ul><li><span class=\"m\">RT-PCR de exudado nasofaríngeo</span>: estándar</li><li>Antígeno rápido: útil con síntomas, menos sensible</li><li>TC/radiografía: <span class=\"m\">vidrio despulido bilateral</span>, periférico y subpleural; luego consolidación</li></ul>", "book": [], "q": []}, {"title": "COVID-19: gravedad y prevención", "html": "<div class=\"bar\">Gravedad</div><ul><li><b>Leve</b>: sin disnea ni hipoxemia</li><li><b>Moderada</b>: neumonía, SatO₂ ≥94 %</li><li><span class=\"m2\">Grave</span>: SatO₂ <94 %, FR >30 o PaO₂/FiO₂ <300</li><li><b>Crítica</b>: SDRA, choque o falla orgánica</li></ul><div class=\"bar\">Prevención</div><ul><li>Vacunas (ARNm, vector viral) y refuerzos</li><li>Mascarilla, ventilación, aislamiento</li></ul>", "book": [], "q": []}, {"title": "COVID-19: tratamiento y complicaciones", "html": "<div class=\"bar\">Tratamiento</div><ul><li>Leve con riesgo: <span class=\"m\">nirmatrelvir/ritonavir</span> en ≤5 d de síntomas</li><li>Remdesivir: alternativa en leve y en hospitalizados</li><li>Hipoxemia con oxígeno: <span class=\"m\">dexametasona 6 mg/día, hasta 10 d</span></li><li>Grave: + baricitinib o tocilizumab</li><li>Tromboprofilaxis con heparina a los hospitalizados</li></ul><div class=\"bar\">Complicaciones</div><ul><li>SDRA e insuficiencia respiratoria</li><li><b>Tormenta de citocinas</b> (IL-6): ferritina y dímero D altos</li><li><span class=\"m2\">Tromboembolia venosa</span> y trombosis arterial</li><li>Miocarditis, lesión renal, fibrosis pulmonar</li><li>COVID prolongado: síntomas >12 semanas</li></ul>", "book": [], "q": [{"rep": 2, "q": "Masculino de 47 años con infiltrado alveolar en todo el pulmón derecho, insuficiencia respiratoria, intubado en UCI. ¿Qué clase de ATS?", "a": "IV", "e": "Ingreso a UCI corresponde a la clase IV de ATS (grave). Las I-II son ambulatorias y la III hospitalización en piso."}]}], "top": [{"rep": 5, "q": "¿Cuál es el tx más adecuado en un px con absceso pulmonar por broncoaspiración?", "a": "Clindamicina y drenaje postural", "e": "Los anaerobios orofaríngeos responden a clindamicina más drenaje postural. La broncoscopia, la lobectomía y la sonda son para fallas o complicaciones, no primera línea."}, {"rep": 5, "q": "¿Cuál es el germen bacteriano que más comúnmente causa neumonía adquirida en la comunidad?", "a": "Neumococo", "e": "Streptococcus pneumoniae es el más frecuente en NAC; Legionella, Chlamydia y S. aureus son menos comunes."}, {"rep": 4, "q": "Hombre de 68 años con cardiopatía isquémica, 72 h con fiebre 39°C, mialgias, odinofagia, rinorrea hialina, tos irritativa e hiperemia faríngea. ¿Agente etiológico más probable?", "a": "Virus influenza A", "e": "Fiebre alta, mialgias y artralgias de inicio agudo orientan a influenza A; rinovirus y VSR dan cuadros catarrales más leves."}, {"rep": 4, "q": "En el caso anterior, ¿cómo confirmaría de forma rápida y con adecuada sensibilidad y especificidad el diagnóstico?", "a": "PCR en tiempo real en exudado faríngeo", "e": "La RT-PCR es el estándar. La prueba rápida es poco sensible; la serología no sirve en fase aguda y no hay antigenuria."}, {"rep": 4, "q": "¿Cómo trataría la infección por este virus?", "a": "Oseltamivir", "e": "Oseltamivir (inhibidor de neuraminidasa) idealmente en las primeras 48 h. Los demás antivirales no actúan sobre influenza."}, {"rep": 4, "q": "Masculino de 25 años con crisis convulsivas desde la infancia, tos productiva abundante y fétida, imagen con nivel hidroaéreo; se dx absceso pulmonar. ¿Cuál es correcta?", "a": "El antibiótico de elección es clindamicina", "e": "La aspiración durante convulsiones favorece anaerobios orales; clindamicina es la elección. El esputo está contaminado por flora oral, Pseudomonas no predomina y la cirugía es excepcional (f02: terapia percusiva, drenaje postural y clindamicina)."}, {"rep": 4, "q": "¿Cuál es el principal parámetro en un derrame paraneumónico que determina complicación y necesidad de drenaje pleural?", "a": "pH ácido", "e": "pH <7.2 es el criterio principal de drenaje. La glucosa estaría baja (no alta); proteínas y DHL altas son solo de exudado. Nota: f02 c2#43 da 'glucosa baja' como respuesta."}, {"rep": 4, "q": "¿Cuál de los siguientes enunciados es correcto en relación a absceso pulmonar?", "a": "Los anaerobios de la boca y faringe son los patógenos más frecuentes", "e": "El origen es microaspiración de flora anaerobia oral. El esputo se contamina, no es útil; la vía hematógena es poco común."}]}]};